# Separately versioned from linear_losses.py; generated by build_optimized_losses.py.
"""Weighted MSE/MAE/Huber linear objectives, independent of feature count.

Consumes TRAINING-only, already preprocessed X/y. Does not read data files,
choose hyperparameters, early-stop on outer Validation, or access Test.
All objectives use a fixed training-target scale and the same L2 convention.
"""
from __future__ import annotations

# Support both direct script execution and package imports after directory grouping.
import sys as _sys
from pathlib import Path as _Path
_sys.path.insert(0, str(_Path(__file__).resolve().parents[1]))
from _paths import REPO_ROOT as _REPO_ROOT, source_path as _source_path

from dataclasses import asdict, dataclass
import numpy as np
from scipy import linalg
from scipy.optimize import minimize


@dataclass(frozen=True)
class LossConfig:
    loss: str = 'huber'
    delta: float = 1.35
    l2: float = 0.01
    max_iter: int = 3000
    tol: float = 1e-6
    chunk_rows: int = 20000
    admm_rho: float = 1.0
    allow_unconverged: bool = False

    def validate(self):
        if self.loss not in ('mse','mae','huber'):
            raise ValueError('loss must be mse, mae or huber')
        if not np.isfinite(self.delta) or self.delta <= 0:
            raise ValueError('delta must be finite and positive')
        if not np.isfinite(self.l2) or self.l2 < 0:
            raise ValueError('l2 must be finite and nonnegative')
        if self.max_iter < 1 or self.chunk_rows < 1 or not np.isfinite(self.tol) or self.tol <= 0:
            raise ValueError('Invalid iteration/tolerance/chunk setting')
        if not np.isfinite(self.admm_rho) or self.admm_rho <= 0:
            raise ValueError('admm_rho must be finite and positive')


def elementwise_loss(residual, loss='huber', delta=1.35):
    """Half squared error, exact absolute error, or standard Huber.

    residual is already in training-scale units. MSE uses 0.5*r**2 so
    Huber matches its quadratic region; evaluation MSE remains mean(r**2).
    """
    r = np.asarray(residual,dtype=np.float64)
    if not np.isfinite(r).all():
        raise ValueError('Residuals must be finite')
    if loss == 'mse': return 0.5*r*r
    if loss == 'mae': return np.abs(r)
    if loss == 'huber' and np.isfinite(delta) and delta > 0:
        a = np.abs(r)
        return np.where(a <= delta, 0.5*r*r, delta*(a-0.5*delta))
    raise ValueError('Invalid loss or Huber delta')


def residual_gradient(residual, loss='huber', delta=1.35):
    r = np.asarray(residual,dtype=np.float64)
    if not np.isfinite(r).all(): raise ValueError('Residuals must be finite')
    if loss == 'mse': return r
    if loss == 'mae': return np.sign(r)  # valid zero subgradient at r=0
    if loss == 'huber' and np.isfinite(delta) and delta > 0:
        return np.clip(r,-delta,delta)
    raise ValueError('Invalid loss or Huber delta')


def normalize_weights(weights,n):
    if weights is None: return np.ones(n,dtype=np.float64)
    w = np.asarray(weights,dtype=np.float64)
    if w.shape != (n,) or not np.isfinite(w).all() or (w<0).any() or not (w>0).any():
        raise ValueError('Weights must be finite, nonnegative, length n, with positive sum')
    # Stable normalization; multiplying ALL weights by a constant is irrelevant.
    w = w/w.max()
    return w/w.mean()


def target_scale(y_train):
    """Fixed across candidate losses: 1.4826*MAD(y_train), then std, then 1.

    This is a robust TARGET dispersion, not an estimate of fitted residual
    sigma. It is never recalculated on validation/test or per-stock predictions.
    """
    y = np.asarray(y_train,dtype=np.float64)
    if y.ndim != 1 or len(y)==0 or not np.isfinite(y).all():
        raise ValueError('Finite, nonempty one-dimensional training targets required')
    value = float(1.4826*np.median(np.abs(y-np.median(y))))
    method = '1.4826*MAD(training_target)'
    if value == 0:
        value = float(y.std())
        method = 'std(training_target); MAD=0'
    if value == 0:
        value,method = 1.0,'constant target; scale=1'
    if not np.isfinite(value) or value <= 0: raise ValueError('Invalid target scale')
    return value,method


def _blocks(x,chunk):
    if isinstance(x, CachedDesign):
        if chunk != x.cached_chunk:
            raise ValueError('Cache chunk must match solver chunk')
        yield from x.cached_blocks
        return
    for start in range(0,len(x),chunk):
        end=min(start+chunk,len(x))
        yield start,end,np.asarray(x[start:end],dtype=np.float64)


def _ax(x,theta,chunk):
    result=np.empty(len(x),dtype=np.float64)
    for a,b,xb in _blocks(x,chunk): result[a:b]=xb@theta[1:]+theta[0]
    return result


def _at(x,v,chunk):
    result=np.zeros(x.shape[1]+1,dtype=np.float64)
    result[0]=v.sum()
    for a,b,xb in _blocks(x,chunk): result[1:]+=xb.T@v[a:b]
    return result


class CachedDesign(np.ndarray):
    """Bounded float64 blocks with precisely the reference block layout."""
    def __new__(cls, x, chunk=20000, max_bytes=2*1024**3):
        import psutil
        x = np.asarray(x)
        required = x.size*8
        if required > max_bytes or required > psutil.virtual_memory().available*.25:
            raise MemoryError('Block cache exceeds memory budget')
        obj = x.view(cls)
        obj.cached_chunk = chunk
        obj.cached_blocks = [(a, min(a+chunk,len(x)),
            np.array(x[a:a+chunk], dtype=np.float64, order='K', copy=True))
            for a in range(0,len(x),chunk)]
        return obj


def _at_pair(x, v, u, chunk):
    result = np.zeros((x.shape[1]+1, 2), dtype=np.float64)
    result[0] = [v.sum(), u.sum()]
    for a,b,xb in _blocks(x,chunk):
        result[1:] += xb.T @ np.column_stack((v[a:b],u[a:b]))
    return result


def _gram(x,w,chunk):
    gram=np.zeros((x.shape[1]+1,x.shape[1]+1),dtype=np.float64)
    gram[0,0]=w.sum()
    for a,b,xb in _blocks(x,chunk):
        wx=xb*w[a:b,None]
        gram[1:,1:]+=xb.T@wx
        gram[0,1:]+=wx.sum(axis=0)
    gram[1:,0]=gram[0,1:]
    return (gram+gram.T)*0.5/len(x)


def objective_gradient(theta,x,y_scaled,weights,config):
    """Gradient w.r.t. [intercept, coefficients] in target-scale units."""
    value=0.0
    gradient=np.zeros_like(theta,dtype=np.float64)
    total=weights.sum()
    for a,b,xb in _blocks(x,config.chunk_rows):
        residual=xb@theta[1:]+theta[0]-y_scaled[a:b]
        value+=np.dot(weights[a:b],elementwise_loss(residual,config.loss,config.delta))/total
        g=weights[a:b]*residual_gradient(residual,config.loss,config.delta)/total
        gradient[0]+=g.sum()
        gradient[1:]+=xb.T@g
    value+=0.5*config.l2*np.dot(theta[1:],theta[1:])
    gradient[1:]+=config.l2*theta[1:]
    return float(value),gradient


def _mse(x,y,w,config):
    gram=_gram(x,w,config.chunk_rows)
    gram[1:,1:]+=config.l2*np.eye(x.shape[1])
    rhs=_at(x,w*y,config.chunk_rows)/len(x)
    theta=linalg.lstsq(gram,rhs,cond=1e-12)[0]
    error=float(np.max(np.abs(gram@theta-rhs)))
    return theta,dict(solver='centered-scale weighted normal equations; intercept unpenalized',
        iterations=1,converged=error<=max(config.tol,1e-10),normal_equation_residual=error)


def _mae_admm(x,y,w,initial,config):
    """Exact LAD objective + L2, solved to numerical ADMM tolerances.

    Auxiliary residual z=A*theta-y; soft threshold w/rho. No smoothing or
    disguised Huber approximation. This is a reference CPU solver; large
    500-feature training still requires workload benchmarking.
    """
    n=len(y)
    rho=config.admm_rho
    matrix=rho*_gram(x,np.ones(n),config.chunk_rows)
    matrix[1:,1:]+=config.l2*np.eye(x.shape[1])
    # Fixed system: factorize once. Pseudoinverse only for singular designs.
    try:
        chol=linalg.cho_factor(matrix,lower=True)
        solve=lambda rhs:linalg.cho_solve(chol,rhs)
    except linalg.LinAlgError:
        inverse=linalg.pinvh(matrix,rtol=1e-12)
        solve=lambda rhs:inverse@rhs
    theta=initial.copy()
    z=_ax(x,theta,config.chunk_rows)-y
    u=np.zeros(n)
    converged=False
    for step in range(1,config.max_iter+1):
        theta=solve(rho*_at(x,y+z-u,config.chunk_rows)/n)
        residual=_ax(x,theta,config.chunk_rows)-y
        v=residual+u
        new_z=np.sign(v)*np.maximum(np.abs(v)-w/rho,0)
        u+=residual-new_z
        primal=float(np.linalg.norm(residual-new_z)/np.sqrt(n))
        # One batched transpose scan, with direct residuals (no Gram recurrence drift).
        projections = _at_pair(x, new_z-z, u, config.chunk_rows)/n
        dual=float(np.max(np.abs(rho*projections[:,0])))
        primal_tol=config.tol*(1+max(np.linalg.norm(residual),np.linalg.norm(new_z))/np.sqrt(n))
        dual_tol=config.tol*(1+float(np.max(np.abs(rho*projections[:,1]))))
        z=new_z
        if primal<=primal_tol and dual<=dual_tol:
            converged=True
            break
    return theta,dict(solver='ADMM exact weighted absolute loss + L2',iterations=step,
        converged=converged,primal_rms=primal,primal_tolerance=float(primal_tol),
        dual_gradient_inf=dual,dual_tolerance=float(dual_tol),rho=rho)


def fit_linear_loss(x_train,y_train,sample_weight=None,config=None):
    """Fit a fresh linear model. X must use preprocessing fitted on Training.

    Supports any feature count. Weights may encode date or ex-ante stock
    priorities; they may NOT depend on future realized Validation/Test returns.
    Returns coefficients in original TARGET units, with the supplied X scale.
    """
    config=config or LossConfig()
    config.validate()
    x=np.asanyarray(x_train)
    y=np.asarray(y_train,dtype=np.float64)
    if x.ndim!=2 or x.shape[0]==0 or x.shape[0]!=len(y) or y.ndim!=1:
        raise ValueError('X must be nonempty n-by-p and y must have length n')
    for _,_,xb in _blocks(x,config.chunk_rows):
        if not np.isfinite(xb).all(): raise ValueError('Preprocess missing features using Training statistics first')
    if not np.isfinite(y).all(): raise ValueError('Nonfinite training targets')
    w=normalize_weights(sample_weight,len(y))
    scale,scale_method=target_scale(y)
    ys=y/scale
    initial,mse_info=_mse(x,ys,w,config)
    if config.loss=='mse':
        theta,info=initial,mse_info
    elif config.loss=='huber':
        result=minimize(objective_gradient,initial,args=(x,ys,w,config),jac=True,
            method='L-BFGS-B',options=dict(maxiter=config.max_iter,gtol=config.tol,
                                         ftol=1e-14,maxls=40))
        theta=result.x
        gradient_norm=float(np.max(np.abs(result.jac)))
        info=dict(solver='L-BFGS-B fixed-scale Huber + L2',iterations=int(result.nit),
            converged=bool(result.success and gradient_norm<=max(10*config.tol,1e-8)),
            gradient_inf=gradient_norm,message=str(result.message))
    else:
        theta,info=_mae_admm(x,ys,w,initial,config)
    if not np.isfinite(theta).all(): raise RuntimeError('Nonfinite solution')
    if not info['converged'] and not config.allow_unconverged:
        raise RuntimeError(f'Fit did not converge; not eligible for comparison: {info}')
    prediction=_ax(x,theta,config.chunk_rows)*scale
    residual=prediction-y
    info.update(training_rmse=float(np.sqrt(np.mean(residual**2))),
        training_mae=float(np.mean(np.abs(residual))),
        normalized_penalized_objective=objective_gradient(theta,x,ys,w,config)[0],
        training_rows=len(y),feature_count=x.shape[1])
    if config.loss=='huber':
        tail=np.abs(residual/scale)>config.delta
        info.update(huber_linear_region_share=float(tail.mean()),
                    huber_weighted_linear_region_share=float(np.average(tail,weights=w)))
    return dict(coefficient=(theta[1:]*scale).tolist(),intercept=float(theta[0]*scale),
        target_scale=scale,target_scale_method=scale_method,
        huber_delta_target_units=float(config.delta*scale) if config.loss=='huber' else None,
        config=asdict(config),diagnostics=info)


def predict_linear_loss(model,x,chunk_rows=20000):
    x=np.asarray(x)
    coefficient=np.asarray(model['coefficient'],dtype=np.float64)
    if x.ndim!=2 or x.shape[1]!=len(coefficient): raise ValueError('Feature count mismatch')
    return _ax(x,np.r_[model['intercept'],coefficient],chunk_rows)
